do $catalog_fixtures$
begin
drop table if exists private.qa_catalog_product_fixtures;
create table private.qa_catalog_product_fixtures (
	product_id uuid primary key,
	revision_id uuid not null unique,
	observation_id uuid not null unique,
	barcode text not null unique,
	product_name text not null,
	brand_owner text not null,
	category_option_id text not null,
	source_reference text not null,
	catalog_source text not null default 'community-reviewed',
	catalog_confidence text not null default 'moderator-reviewed',
	evidence_source text not null default 'user-label',
	evidence_reference text,
	evidence_license text not null default 'Local QA fixture',
	evidence_confidence text not null default 'moderator-reviewed',
	evidence_method text not null default 'label-review',
	source_category text,
	raw_source_payload jsonb,
	food jsonb not null
);

