insert into private.qa_catalog_product_fixtures (
	product_id,
	revision_id,
	observation_id,
	barcode,
	product_name,
	brand_owner,
	category_option_id,
	source_reference,
	catalog_source,
	catalog_confidence,
	evidence_source,
	evidence_reference,
	evidence_license,
	evidence_confidence,
	evidence_method,
	source_category,
	raw_source_payload,
	food
)
select
	('84000000-0000-4000-8000-' || lpad((fixture_number * 10 + 1)::text, 12, '0'))::uuid,
	('84000000-0000-4000-8000-' || lpad((fixture_number * 10 + 2)::text, 12, '0'))::uuid,
	('84000000-0000-4000-8000-' || lpad((fixture_number * 10 + 3)::text, 12, '0'))::uuid,
	barcode,
	product_name,
	brand_owner,
	category_option_id,
	fdc_id::text,
	'usda',
	'imported',
	'usda',
	fdc_id::text,
	'CC0-1.0',
	'imported',
	'exact-barcode',
	source_category,
	raw_source_payload,
	food
from qa_usda_products
where public.is_valid_gtin(barcode);

