	product_id,
	revision_id,
	observation_id,
	barcode,
	product_name,
	brand_owner,
	category_option_id,
	source_reference,
	catalog_source,
	catalog_confidence,
	evidence_source,
	evidence_reference,
	evidence_license,
	evidence_confidence,
	evidence_method,
	source_category,
	raw_source_payload,
	food
)
select
	('84000000-0000-4000-8000-' || lpad((fixture_number * 10 + 1)::text, 12, '0'))::uuid,
	('84000000-0000-4000-8000-' || lpad((fixture_number * 10 + 2)::text, 12, '0'))::uuid,
	('84000000-0000-4000-8000-' || lpad((fixture_number * 10 + 3)::text, 12, '0'))::uuid,
	barcode,
	product_name,
	brand_owner,
	category_option_id,
	fdc_id::text,
	'usda',
	'imported',
