	'imported',
	'exact-barcode',
	source_category,
	jsonb_build_object(
		'source', 'USDA FoodData Central',
		'fdcId', fdc_id,
		'description', source_description,
		'dataType', 'Branded',
		'gtinUpc', barcode,
		'publicationDate', published_date,
		'modifiedDate', modified_date,
		'brandOwner', brand_owner,
