insert into public.shared_product_revisions (
	id,
	shared_product_id,
	revision_number,
	category_option_id,
	food,
	source,
	source_reference,
	change_summary,
	label_observed_at
)
select
	revision_id,
	product_id,
	1,
	category_option_id,
	food,
	catalog_source,
	source_reference,
	'{"version":1,"fixture":true,"changes":[]}'::jsonb,
	'2026-08-01T00:00:00Z'
from private.qa_catalog_product_fixtures
on conflict (id) do update set
	category_option_id = excluded.category_option_id,
	food = excluded.food,
	source = excluded.source,
	source_reference = excluded.source_reference,
	change_summary = excluded.change_summary,
	label_observed_at = excluded.label_observed_at;

insert into public.shared_product_observations (
	id,
	barcode,
	source,
	source_reference,
	source_license,
	raw_payload,
	normalized_food,
	content_hash,
	observed_at
)
select
	observation_id,
	barcode,
	evidence_source,
	coalesce(evidence_reference, source_reference),
	evidence_license,
	coalesce(raw_source_payload, jsonb_build_object('fixture', true, 'fixtureVersion', 1, 'label', food)),
	food,
	encode(extensions.digest(coalesce(evidence_reference, source_reference) || food::text, 'sha256'), 'hex'),
	'2026-08-01T00:00:00Z'
from private.qa_catalog_product_fixtures
on conflict (id) do update set
	source_reference = excluded.source_reference,
	source_license = excluded.source_license,
	raw_payload = excluded.raw_payload,
	normalized_food = excluded.normalized_food,
	content_hash = excluded.content_hash,
	observed_at = excluded.observed_at;

with selected_fields as (
	select
		fixture.product_id,
		fixture.observation_id,
		field.field_path,
		coalesce(nullif(field.source_value, 'null'::jsonb), field.normalized_value) as source_value,
		field.normalized_value,
		fixture.evidence_confidence,
		fixture.evidence_method
	from private.qa_catalog_product_fixtures fixture
	join public.custom_food_category_options category
		on category.id = fixture.category_option_id
	cross join lateral (
		values
			('productName', coalesce(fixture.raw_source_payload -> 'description', to_jsonb(fixture.product_name)), to_jsonb(fixture.product_name)),
			('brandOwner', coalesce(fixture.raw_source_payload -> 'brandOwner', to_jsonb(fixture.brand_owner)), to_jsonb(fixture.brand_owner)),
			('categories', coalesce(to_jsonb(fixture.source_category), to_jsonb(array[category.label])), to_jsonb(array[category.label])),
			('ingredients', coalesce(fixture.raw_source_payload -> 'ingredients', fixture.food -> 'ingredients'), fixture.food -> 'ingredients'),
			('allergens', fixture.food -> 'allergens', fixture.food -> 'allergens'),
			('traces', fixture.food -> 'traces', fixture.food -> 'traces'),
			('dietaryTags', fixture.food -> 'dietaryTags', fixture.food -> 'dietaryTags'),
			('labels', fixture.food -> 'labels', fixture.food -> 'labels'),
			('structuredIngredients', fixture.food -> 'structuredIngredients', fixture.food -> 'structuredIngredients'),
			('ingredientAnalysis', fixture.food -> 'ingredientAnalysis', fixture.food -> 'ingredientAnalysis'),
			('additives', fixture.food -> 'additives', fixture.food -> 'additives'),
			('precautionaryStatements', fixture.food -> 'precautionaryStatements', fixture.food -> 'precautionaryStatements'),
			('package', fixture.food -> 'packageQuantity', fixture.food -> 'packageQuantity'),
			('alcoholByVolume', fixture.food -> 'alcoholByVolume', fixture.food -> 'alcoholByVolume'),
			('regulatoryDisclosure', fixture.food -> 'regulatoryDisclosure', fixture.food -> 'regulatoryDisclosure'),
			('sourceMetadata', fixture.raw_source_payload, fixture.food -> 'sourceMetadata'),
			('serving', coalesce(fixture.raw_source_payload -> 'serving', fixture.food -> 'foodServings'), fixture.food -> 'foodServings'),
			(
				'servingWeightGrams',
				coalesce(
					fixture.raw_source_payload -> 'serving' -> 'servingSize',
					fixture.raw_source_payload -> 'servingSize',
					fixture.food -> 'servingSize',
					fixture.food -> 'foodServings' -> 0 -> 'gramWeight'
				),
				coalesce(
					fixture.food -> 'servingSize',
					fixture.food -> 'foodServings' -> 0 -> 'gramWeight'
				)
			),
			('nutrition', coalesce(fixture.raw_source_payload -> 'foodNutrients', fixture.food -> 'foodNutrients'), fixture.food -> 'foodNutrients')
	) field(field_path, source_value, normalized_value)
	where field.normalized_value is not null
), nutrient_fields as (
	select
		fixture.product_id,
		fixture.observation_id,
		'nutrient:' || (nutrient.value ->> 'nutrientId') as field_path,
		coalesce(
			(
				select source_nutrient.value
				from jsonb_array_elements(coalesce(fixture.raw_source_payload -> 'foodNutrients', '[]'::jsonb)) source_nutrient(value)
				where source_nutrient.value ->> 'nutrientId' = nutrient.value ->> 'nutrientId'
				limit 1
			),
			nutrient.value
		) as source_value,
		nutrient.value as normalized_value,
		fixture.evidence_confidence,
		fixture.evidence_method
	from private.qa_catalog_product_fixtures fixture
	cross join lateral jsonb_array_elements(fixture.food -> 'foodNutrients') nutrient(value)
)
insert into public.shared_product_field_provenance (
	shared_product_id,
	observation_id,
	field_path,
	source_value,
	normalized_value,
	selected,
	confidence,
	verification_method
)
select
	product_id,
	observation_id,
	field_path,
	source_value,
	normalized_value,
	true,
	evidence_confidence,
	evidence_method
from (
	select * from selected_fields
	union all
	select * from nutrient_fields
) fields
on conflict (shared_product_id, observation_id, field_path) do update set
	source_value = excluded.source_value,
	normalized_value = excluded.normalized_value,
	selected = excluded.selected,
	confidence = excluded.confidence,
	verification_method = excluded.verification_method;

insert into public.food_nutrients (
	shared_product_id,
	nutrient_id,
	amount_per_100g,
	unit_name,
	value_origin,
	source,
	source_reference,
	source_observation_id,
	confidence,
	value_status,
	source_nutrient_key,
	mapping_status,
	mapping_method,
	mapping_review_reference
)
select
	fixture.product_id,
	(nutrient.value ->> 'nutrientId')::bigint,
	(nutrient.value ->> 'value')::numeric,
	nutrient.value ->> 'unitName',
	nutrient.value ->> 'valueOrigin',
	fixture.evidence_source,
	coalesce(fixture.evidence_reference, fixture.source_reference),
	fixture.observation_id,
	fixture.evidence_confidence,
	nutrient.value ->> 'valueStatus',
	case
		when fixture.evidence_source = 'usda' then nutrient.value ->> 'nutrientId'
		else 'local-qa:' || (nutrient.value ->> 'nutrientId')
	end,
	'canonical',
	case when fixture.evidence_source = 'usda' then 'exact-usda-fdc-nutrient-id' else 'local-qa-label-fixture' end,
	'docs/development/database-testing.md'
from private.qa_catalog_product_fixtures fixture
cross join lateral jsonb_array_elements(fixture.food -> 'foodNutrients') nutrient(value)
on conflict (shared_product_id, nutrient_id) where shared_product_id is not null
do update set
	amount_per_100g = excluded.amount_per_100g,
	unit_name = excluded.unit_name,
	value_origin = excluded.value_origin,
	source = excluded.source,
	source_reference = excluded.source_reference,
	source_observation_id = excluded.source_observation_id,
	confidence = excluded.confidence,
	value_status = excluded.value_status,
	source_nutrient_key = excluded.source_nutrient_key,
	mapping_status = excluded.mapping_status,
	mapping_method = excluded.mapping_method,
	mapping_review_reference = excluded.mapping_review_reference;

insert into public.food_servings (
	shared_product_id,
	serving_order,
	label,
	gram_weight,
	amount,
	unit_key,
	is_primary,
	measure_type,
	is_household_measure,
	source_measure_key,
	origin,
	gram_weight_method,
	source,
	source_reference,
	source_observation_id,
	confidence
)
select
	fixture.product_id,
	serving.position::smallint,
	serving.value ->> 'label',
	(serving.value ->> 'gramWeight')::numeric,
	(serving.value ->> 'amount')::numeric,
	serving.value ->> 'unitKey',
	(serving.value ->> 'isPrimary')::boolean,
	serving.value ->> 'measureType',
	(serving.value ->> 'isHouseholdMeasure')::boolean,
	serving.value ->> 'sourceMeasureKey',
	serving.value ->> 'origin',
	serving.value ->> 'gramWeightMethod',
	fixture.evidence_source,
	coalesce(fixture.evidence_reference, fixture.source_reference),
	fixture.observation_id,
	fixture.evidence_confidence
from private.qa_catalog_product_fixtures fixture
cross join lateral jsonb_array_elements(fixture.food -> 'foodServings')
	with ordinality serving(value, position)
on conflict (shared_product_id, serving_order) where shared_product_id is not null
do update set
	label = excluded.label,
	gram_weight = excluded.gram_weight,
	amount = excluded.amount,
	unit_key = excluded.unit_key,
	is_primary = excluded.is_primary,
	measure_type = excluded.measure_type,
	is_household_measure = excluded.is_household_measure,
	source_measure_key = excluded.source_measure_key,
	origin = excluded.origin,
	gram_weight_method = excluded.gram_weight_method,
	source = excluded.source,
	source_reference = excluded.source_reference,
	source_observation_id = excluded.source_observation_id,
	confidence = excluded.confidence;

